 R([".tlc .seg",".tlc .tools button.t",".tlc .xb",".tl-opt"],"background:var(--s2)!important;border-color:var(--line)!important;color:var(--txt)");
 ONLY("light",[".card",".nft-hub .nft-card"],"box-shadow:var(--shadow)");
 ONLY("light",["#bg"],"display:none");
