".bk{align-self:flex-start;width:40px;height:40px;border-radius:13px;background:var(--s2);border:1.5px solid var(--line);display:grid;place-items:center}",
".orb{position:relative;width:92px;height:92px;display:grid;place-items:center;margin-top:6px}.orb:before,.orb:after{content:\"\";position:absolute;border:1.5px solid #ff9f2e66;border-radius:50%;animation:spin 9s linear infinite}.orb:before{width:92px;height:38px;transform:rotate(-30deg)}.orb:after{width:62px;height:92px;border-color:#ffffff40;animation-duration:13s;animation-direction:reverse;transform:rotate(40deg)}.orb img{width:46px;height:46px;position:relative;z-index:1;filter:drop-shadow(0 6px 14px #ff9f2e88)}",
".lgn{font:800 22px 'Bricolage Grotesque',sans-serif;margin-top:10px}.lgt{font:500 9.5px 'DM Mono',monospace;letter-spacing:.18em;color:var(--am);text-transform:uppercase;margin-top:2px}",
".lg h2{margin-top:22px;font-size:26px;text-align:center}.lg .sub{color:var(--mut);text-align:center;margin:6px 0 18px;font-size:13px;max-width:300px}",
".f{width:100%;max-width:380px;display:grid;gap:10px}.fld{position:relative;display:block;border:1.5px solid var(--line);border-radius:16px;padding:21px 14px 8px;background:#090e13}.fld:focus-within{border-color:var(--am);box-shadow:0 0 0 3px #ffb02e22}.fld>span{position:absolute;left:14px;top:7px;font-size:10.5px;font-weight:700;color:var(--mut)}.fld input{width:100%;background:none;border:0;outline:0;font-size:16px;font-weight:700;padding:2px 0 0}",
".fld .sh{position:absolute;right:12px;top:50%;translate:0 -50%;color:var(--mut);font-size:11.5px;font-weight:800}",
".err{color:#ff5d73;font-size:12px;min-height:16px;text-align:center}.lk{color:var(--am);font-weight:800;font-size:12.5px}.sw{margin-top:16px;color:var(--mut);font-size:13px;text-align:center}.sw button{color:var(--am);font-weight:800}",
".lg{align-items:stretch;max-width:480px;margin:0 auto;width:100%;padding:calc(12px + env(safe-area-inset-top,0px)) 20px 24px}",
".lt{display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:8px;min-height:40px}.lt b{text-align:center;font:800 16px 'Bricolage Grotesque',sans-serif}.lt .lk{font-size:13px}",
".lb{display:flex;flex-direction:column;flex:1;padding-top:16px}.lb h2{text-align:left;margin-top:10px;font-size:26px}.lb .big{font-size:28px;margin:6px 0 18px}.lb .sub{color:var(--mut);margin:6px 0 16px;font-size:13px;text-align:left;max-width:none}.lb .orb{margin:0 auto}.lb .lgn,.lb .lgt{text-align:center}.lb .lgn{margin-top:8px}",
".tb{display:flex;gap:6px;margin-bottom:12px}.tb button{padding:8px 16px;border-radius:999px;color:#6b7886;font-weight:800;font-size:14px}.tb button.on{background:var(--s2);color:#fff}",
".fl{position:relative;display:flex;align-items:center;gap:10px;height:52px;padding:0 14px;border:1.5px solid var(--line);border-radius:16px;background:#090e13}.fl:focus-within{border-color:var(--am);box-shadow:0 0 0 3px #ffb02e22}.fl i{color:var(--mut);display:grid}.fl input,.fl select{flex:1;min-width:0;background:none;border:0;outline:0;font-size:16px;font-weight:700;color:#f5f7fa;appearance:none;-webkit-appearance:none}.fl select{flex:none;width:76px;border-right:1.5px solid var(--line);margin-right:2px}.fl select option{background:#141c24}",
".fl .sh{color:var(--mut);font-size:12px;font-weight:800}.fl.sel{height:58px}.fl.sel .fg{font-size:24px}.fl.sel b{flex:1;font-size:16px}.fl.sel em{font-style:normal;color:var(--mut);font-size:13px}.fl.sel select{position:absolute;inset:0;width:100%;opacity:0;border:0;margin:0}",
".lbl{font-size:13px;font-weight:800;margin:16px 0 8px;color:#e6ebf0}.hint{color:var(--mut);font-size:11.5px;margin:6px 2px 0}.tc{display:flex;gap:10px;align-items:flex-start;margin:16px 0 4px;color:var(--mut);font-size:12.5px}.tc input{accent-color:#ffb02e;width:18px;height:18px;margin:0}",
".lb .err{text-align:left;min-height:18px;margin-top:8px}.lb .btn{margin-top:8px}.grow{flex:1;min-height:40px}.lb .lk.c{margin:16px auto 0}",
".dv{display:flex;align-items:center;gap:12px;color:#6b7886;font-size:13px;margin-top:26px}.dv:before,.dv:after{content:\"\";flex:1;height:1px;background:var(--line)}",
".sr{display:flex;justify-content:center;gap:16px;margin-top:16px}.sr button{width:52px;height:52px;border-radius:50%;border:1.5px solid var(--line);display:grid;place-items:center}.sr svg{width:22px;height:22px}",
".who2{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.who2 b{font-size:15px}.who2 .lk{display:inline-flex;align-items:center;gap:4px}.who2 svg{width:15px;height:15px}",
".cd6{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:20px}.cd6 input{width:100%;height:56px;border-radius:14px;background:#090e13;border:1.5px solid var(--line);text-align:center;font-size:22px;font-weight:800;outline:0;color:#f5f7fa}.cd6 input:focus{border-color:var(--am)}",
".rs{display:flex;justify-content:space-between;align-items:center;margin-top:22px;color:#6b7886;font-size:13px;font-weight:700}.rs .lk{display:inline-flex;align-items:center;gap:6px}.rs svg{width:16px;height:16px}",
".cap{position:fixed;inset:0;z-index:50;background:#000b;display:grid;place-items:center;padding:20px}",
".cdb{width:100%;max-width:340px;padding:18px;border-radius:22px;background:var(--s1);border:1.5px solid var(--line);border-top:4px solid var(--am)}.cdb h3{font-size:16px;text-align:center;margin-bottom:14px}",
".pz{position:relative;height:auto;aspect-ratio:1/1;width:min(100%,220px);margin:0 auto;border-radius:14px;overflow:hidden;background:radial-gradient(120% 100% at 20% 0,#2a1a0c,transparent 70%),linear-gradient(135deg,#1d2832,#0d1319)}",
".ho,.pc{position:absolute;top:50%;margin-top:-28px;width:56px;height:56px;clip-path:polygon(25% 5%,75% 5%,100% 50%,75% 95%,25% 95%,0 50%)}.ho{background:#000b}.pc{left:0;background:var(--grad);transition:none}",
".ok{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:8px;background:#0d1319ee;color:#3ddc97;font-weight:800}",
".tk{position:relative;height:44px;margin:14px auto 0;width:min(100%,220px);border-radius:22px;background:var(--s2);display:grid;place-items:center;color:var(--mut);font-size:12.5px;font-weight:700}.hd{position:absolute;left:0;top:0;width:56px;height:100%;border-radius:22px;background:var(--grad);color:#1b1006;display:grid;place-items:center;touch-action:none;cursor:grab}",
".cf{display:flex;gap:14px;margin-top:14px;color:var(--mut)}.cf svg{width:22px;height:22px}",
"/* design spec: card 819x930, puzzle 727x485, track 727x45, button 196x122 (scaled via cqw, 1cqw = card width/100) */",
"#cap .cdb{container-type:inline-size;width:100%;max-width:340px;aspect-ratio:819/930;background:#fff;color:#2b2f3a;border:0;border-top:1.76cqw solid #f5a53a;border-radius:3.5cqw;padding:5.29cqw 5.617cqw 5.55cqw}",
":host([data-env='desktop']) #cap .cdb{max-width:min(500px,calc((100vh - 80px)*.8806))}",
"#cap .cdb h3{color:#2b2f3a;font:500 4.7cqw/5.6cqw 'Hanken Grotesk',system-ui,sans-serif;margin:0 0 5.59cqw}",
"#cap .pz{width:100%;aspect-ratio:727/485;height:auto;margin:0;border-radius:2.4cqw}",
"#cap .pz .hw,#cap .pz .pw{position:absolute;left:0;top:0;width:19.2%;height:25.9%;margin:0;filter:drop-shadow(0 0 1.5px #fff)}",
"#cap .pz .pw{z-index:2;filter:drop-shadow(0 0 1.5px #fff) drop-shadow(0 3px 5px #0008)}",
"#cap .pz .hw i,#cap .pz .pcz{position:absolute;inset:0;display:block;clip-path:polygon(25% 3%,75% 3%,100% 50%,75% 97%,25% 97%,0 50%)}",
"#cap .pz .hw i{background:#0a0e18b3}#cap .pz .pcz{background:linear-gradient(135deg,#ffffff88,#ffffff33)}",
"#cap .tk{display:block;width:100%;aspect-ratio:727/45;height:auto;margin:6.76cqw 0 0;border-radius:99px;background:#dfe3ec}",
"#cap .tk span{display:none}",
"#cap .hd{width:26.96%;height:271%;top:-85.5%;border-radius:99px;background:linear-gradient(180deg,#f7b55e,#f3a043);box-shadow:0 2px 0 #d98a2e;color:#fff}",
"#cap .cf{margin:12.06cqw 0 0 1.2cqw;gap:3.8cqw;color:#8a8f99}#cap .cf button{width:6.18cqw;height:6.18cqw;display:grid;place-items:center}#cap .cf svg{width:100%;height:100%}",
