var NFTSORT="popular",NFTFAV={};try{NFTFAV=JSON.parse(localStorage.getItem("tm.nftfav")||"{}")}catch(e){NFTFAV={}}if(!NFTFAV||typeof NFTFAV!=="object"||Array.isArray(NFTFAV))NFTFAV={};
var NFTLIVE=[],NFTLOADING=false,NFTQUERY="",NFTERROR="",NFTTIMER=null,NFTREQ=0,NFTCOLLECTION="azuki",NFTCHAIN="ethereum";var NFTSHOWN=false,NFTSTALE=false,NFTVIEW="collections",NFTCOLLECTIONS=[],NFTCOLLECTIONSCHAIN="",NFTCOLLECTIONSLOADING=false,NFTSELECTED=null,NFTITEMSCOLLECTION="",NFTITEMSREQ=0,NFTEXPLORECHAIN="",NFTEXPLORELOADING=false,NFTEXPLOREFAIL={};
var NFT_SNAP="tm.nft.snapshot.v1.";
function nftSnapKey(t){return NFT_SNAP+NFTCHAIN+"."+encodeURIComponent(String(t).toLowerCase())}
function nftSnapSave(t,a){try{localStorage.setItem(nftSnapKey(t),JSON.stringify({savedAt:Date.now(),items:a}))}catch(e){}}
function nftSnapLoad(t){try{var s=JSON.parse(localStorage.getItem(nftSnapKey(t))||"null");if(s&&s.items&&s.items.length&&Date.now()-s.savedAt<6048e5)return s.items}catch(e){}return null}
function loadLiveNFTs(query){
 var term=(query||"NFT").trim()||"NFT";
 if(NFTQUERY===term&&(NFTLOADING||NFTLIVE.length))return;
 if(NFTTIMER)clearTimeout(NFTTIMER);
 if(!NFTLIVE.length){var sn=nftSnapLoad(term);if(sn){NFTLIVE=sn;NFTSTALE=true}}
 NFTTIMER=setTimeout(function(){
  var req=++NFTREQ;if(NFTQUERY!==term)NFTSHOWN=false;NFTQUERY=term;NFTLOADING=true;NFTERROR="";
  fetch("/api/nfts?search="+encodeURIComponent(term)+"&chain="+encodeURIComponent(NFTCHAIN)+"&limit=24",{cache:"no-store"})
   .then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.message||"OpenSea request failed.");return d})})
   .then(function(d){if(req!==NFTREQ)return;NFTLIVE=(d.items||[]).map(function(n){return {n:n.name,m:"NFTs",p:typeof n.price==="number"?n.price:null,c:null,k:"NFT",h:0,col:MC.NFTs||"#8b7bff",image:n.image,collection:n.collection,collectionSlug:n.collectionSlug,contract:n.contract,tokenId:n.tokenId,currency:n.currency,marketplaceUrl:n.marketplaceUrl,chain:n.chain||NFTCHAIN,sales24h:n.sales24h,volume24h:n.volume24h,volume24hSymbol:n.volume24hSymbol}});NFTERROR=d.message||"";if(NFTLIVE.length){NFTSTALE=false;nftSnapSave(term,NFTLIVE)}else{var s2=nftSnapLoad(term);if(s2){NFTLIVE=s2;NFTSTALE=true}}})
   .catch(function(e){if(req!==NFTREQ)return;if(!NFTLIVE.length){var s3=nftSnapLoad(term);if(s3){NFTLIVE=s3;NFTSTALE=true}}NFTERROR=e.message||"Could not load OpenSea results.";})
   .finally(function(){if(req!==NFTREQ)return;NFTLOADING=false;if(st.tab==="Markets"&&st.mm==="NFTs")softDraw();if(NFTSTALE&&st.mm==="NFTs")setTimeout(function(){NFTQUERY="";loadLiveNFTs(term)},15000)});
 },250);
}
function loadNFTCollections(force){
 if(NFTCOLLECTIONSCHAIN===NFTCHAIN&&!force)return;
 if(NFTCOLLECTIONSLOADING)return;
 var snap=nftSnapLoad("collections");
 if(snap&&NFTCOLLECTIONSCHAIN!==NFTCHAIN){NFTCOLLECTIONS=snap;NFTCOLLECTIONSCHAIN=NFTCHAIN}
 NFTCOLLECTIONSLOADING=true;NFTERROR="";
 fetch("/api/nft-collections?chain="+encodeURIComponent(NFTCHAIN)+"&limit=48",{cache:"no-store"})
 .then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.message||"Could not load NFT collections");return d})})
 .then(function(d){var fresh=Array.isArray(d.collections)?d.collections:[];if(fresh.length){NFTCOLLECTIONS=fresh;nftSnapSave("collections",fresh)}else if(!NFTCOLLECTIONS.length){NFTCOLLECTIONS=fresh}NFTCOLLECTIONSCHAIN=NFTCHAIN;NFTERROR=d.message||""})
 .catch(function(e){if(!NFTCOLLECTIONS.length){var cached=nftSnapLoad("collections");if(cached)NFTCOLLECTIONS=cached}NFTCOLLECTIONSCHAIN=NFTCHAIN;NFTERROR=e.message||"Could not load NFT collections"})
 .finally(function(){NFTCOLLECTIONSLOADING=false;if(st.tab==="Markets"&&st.mm==="NFTs")softDraw()});
}
