 var req=++NFTITEMSREQ,chain=NFTCHAIN,top=NFTCOLLECTIONS.slice(0,20).filter(function(c){return c&&c.slug});
 var snap=nftSnapLoad("explore-top20");if(snap){NFTLIVE=snap;NFTSTALE=true}
