var TM_QUOTE_SNAPSHOT_PREFIX="tm.market.quote.snapshot.v1.";
function tmQuoteSnapshotKey(it){return TM_QUOTE_SNAPSHOT_PREFIX+encodeURIComponent(String(it.m||"market"))+"."+encodeURIComponent(String(it.n||"instrument"))}
function tmSaveQuoteSnapshot(it,q){try{if(!it||!q||!(Number(q.price)>0))return;var payload={price:Number(q.price),changePercent:Number.isFinite(Number(q.changePercent))?Number(q.changePercent):null,currency:q.currency||it.quoteCurrency||it.unit||"USD",marketTime:q.marketTime||it.quoteTime||null,exchange:q.exchange||null};localStorage.setItem(tmQuoteSnapshotKey(it),JSON.stringify({savedAt:Date.now(),data:payload}))}catch(e){}}
function tmRestoreQuoteSnapshot(it){try{if(!it)return false;var raw=localStorage.getItem(tmQuoteSnapshotKey(it));if(!raw)return false;var saved=JSON.parse(raw),data=saved&&saved.data,maxAge=it.m==="Forex"&&!it.assetClass?14*24*60*60*1000:30*24*60*60*1000;if(!data||!(Number(data.price)>0)||!saved.savedAt||Date.now()-Number(saved.savedAt)>maxAge)return false;it.p=Number(data.price);it.c=Number.isFinite(Number(data.changePercent))?Number(data.changePercent):it.c;it.quoteStatus="cached";it.quoteTime=data.marketTime||null;it.quoteCurrency=data.currency||it.unit||"USD";it.snapshotAt=Number(saved.savedAt);return true}catch(e){return false}}
