function scoutPicks(tab,n){
 var L=items.filter(function(i){return typeof i.p==="number"&&typeof i.c==="number"});
 if(tab==="Trending")L=L.slice().sort(function(a,b){return Math.abs(b.c)-Math.abs(a.c)});
 else if(tab==="Highest Return")L=L.slice().sort(function(a,b){return b.c-a.c});
 else{var seen={},out=[];L.slice().sort(function(a,b){return b.c-a.c}).forEach(function(i){var g=i.assetClass||i.m;if(!seen[g]&&i.c>0){seen[g]=1;out.push(i)}});L=out}
 return L.slice(0,n||5)
}
function scoutWhy(i,tab){
 var g=i.assetClass||i.m,c=(i.c>=0?"+":"")+i.c.toFixed(2)+"%";
 if(tab==="Trending")return "One of the biggest 24h moves ("+c+") across all markets right now.";
 if(tab==="Highest Return")return "Best 24h performance among live markets at "+c+".";
 return "Leading "+g+" mover over 24h ("+c+")."
}
