document.addEventListener("click",function(e){var t=e.target;if(!t||!t.closest)return;var a=t.closest("[data-scout-tab]");if(a){SC.tab=a.dataset.scoutTab;drawPage();return}if(t.closest("[data-scout-rescan]")){scoutReset();drawPage();return}if(t.closest("[data-scout-all]")){SC.full=!SC.full;drawPage();return}if(t.closest("[data-scout-share]")){var u={title:"TradeMate Scout",url:location.href};if(navigator.share)navigator.share(u).catch(function(){});else toast("Sharing isn't available on this device")}});
function scoutInfo(){return '<button class="rt" data-toast="Scout ranks live markets by 24h movement" aria-label="Info">'+si("info")+'</button>'}
function scoutPage(){
 var wide=scoutWide(),done=SC.phase==="results",F=scoutFeat(),R=scoutRows(),tabs=["Recommended","Trending","Highest Return"];
 var hero='<div class="sc-hero'+(done?"":" scan")+'"><div class="sc-hl"><button class="sc-start" data-scout-rescan>'+si("scout")+'Start Scouting '+si("chev")+'</button></div>'+
  '<div class="sc-hc">'+scoutGlobe()+'<h4>'+(done?"Scan complete":"Scanning Global Contracts...")+'</h4><p class="sc-sub">'+(done?"Top contracts are listed below":"Finding the best opportunities for you worldwide")+'</p>'+scoutSteps()+'</div></div>';
 var live='<aside class="sc-live"><div class="sc-lh"><span><i></i>Live Market Activity</span><button data-tab="Markets">View All →</button></div>'+(F.length?F.map(function(r){var i=r.i;return '<button class="sc-lr" data-open="'+esc(i.n)+'">'+scoutCoin(i)+'<div><b>'+esc(r.nm)+'</b><small>'+scoutPx(i)+scoutChg(i).replace("<em","<span").replace("</em>","</span>")+'</small></div>'+scoutSpark(i,64,28,r.col)+'</button>'}).join(""):'<p class="sc-note" style="padding:16px 0">Waiting for live prices…</p>')+'</aside>';
 var rec='<section class="sc-rec"><div class="sc-rh">'+si("star")+'<div><h2>Recommended <em>for You</em></h2><small>Top contracts matching your interests globally</small></div><button class="btn sm o" data-scout-all><span class="sc-l">'+(SC.full?"Show Fewer":"View All Recommendations")+'</span><span class="sc-s">'+(SC.full?"Fewer":"View All")+'</span> '+si("arrow","width:14px;height:14px;vertical-align:-2px")+'</button></div>'+
  (SC.full?'<div class="sc-tabs">'+tabs.map(function(t){return '<button class="'+(SC.tab===t?"on":"")+'" data-scout-tab="'+t+'">'+t+'</button>'}).join("")+'</div>':'')+
  (R.length?'<div class="sc-rg">'+R.map(scoutCardD).join("")+'</div>':'<div class="sc-empty"><b>Waiting for live prices</b>Market data is still loading.<br><button class="btn sm o" style="margin-top:12px" data-scout-rescan>Scan again</button></div>')+
  '<p class="sc-note">Past price movement does not guarantee future returns.</p></section>';
 return hdr("Contract Scout",wide?{}:{right:scoutInfo()})+'<div class="sc-p'+(wide?" wide":"")+'"><div class="sc-dtop">'+hero+live+'</div>'+rec+'</div>'}
function scoutMobile(){
 if(SC.phase!=="results"){
  return hdr("Contract Scout",{right:scoutInfo()})+'<div class="sc-w"><div class="sc-map m">'+scoutGlobe()+'</div><div class="sc-cap2"><h3>Scanning Global Contracts…</h3><p class="sc-sub">Finding the best opportunities for you worldwide</p></div>'+scoutSteps()+
   '<div class="sc-rc"><span class="sc-radar"></span><ul class="sc-chk">'+["Exploring global markets…","Analysing contract trends…","Evaluating risk & returns…"].map(function(s,k){return '<li class="'+(k<=SC.step?"on":"")+'"><b>'+si("check")+'</b>'+s+'</li>'}).join("")+'</ul></div>'+
   '<div class="sc-stick"><div class="sc-bar">Searching Worldwide…'+si("bars")+'</div></div></div>'}
 var L=scoutMobRows(),tabs=["Recommended","Trending","Highest Return"];
 return hdr("Scout Results",{right:'<button class="rt" data-scout-share aria-label="Share">'+si("share")+'</button>'})+'<div class="sc-w"><div class="sc-trophy"><span>'+si("trophy")+'</span></div><h3>Top Contract Recommendations</h3><p class="sc-sub">Based on your profile, market trends and goals</p>'+
  '<div class="sc-tabs">'+tabs.map(function(t){return '<button class="'+(SC.tab===t?"on":"")+'" data-scout-tab="'+t+'">'+t+'</button>'}).join("")+'</div>'+
  (L.length?'<div class="sc-list">'+L.map(scoutCardM).join("")+'</div>':'<div class="sc-empty"><b>Waiting for live prices</b>Market data is still loading.<br><button class="btn sm o" style="margin-top:12px" data-scout-rescan>Scan again</button></div>')+
  '<p class="sc-note">Past price movement does not guarantee future returns.</p><div class="sc-stick"><button class="sc-go" data-tab="Markets">'+si("bars")+'Continue Exploring</button></div></div>'}
