".tm-mw .nft-hub .nft-stats-strip{display:flex;gap:0;margin:0 16px 14px;border:1px solid var(--line);border-radius:14px;background:var(--s1);overflow:hidden}",
".tm-mw .nft-hub .nft-stats-strip>div{flex:1;padding:9px 12px;border-right:1px solid var(--line);min-width:0}",
".tm-mw .nft-hub .nft-stats-strip>div:last-child{border-right:0}",
".tm-mw .nft-hub .nft-stats-strip small{display:block;font-size:10px;color:var(--mut);font-weight:600;letter-spacing:.04em;text-transform:uppercase}",
".tm-mw .nft-hub .nft-stats-strip b{display:block;margin-top:2px;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}",
".tm-mw .nft-hub .nft-toolbar{display:flex;gap:10px;margin:0 16px 12px}",
".tm-mw .nft-hub .nft-search{flex:1;min-width:0;height:44px;padding:0 14px;border-radius:14px;box-shadow:none;background:var(--s1);border:1px solid var(--line);gap:10px}",
".tm-mw .nft-hub .nft-search svg{width:18px;height:18px}",
".tm-mw .nft-hub .nft-search input{font-size:14px}",
".tm-mw .nft-hub .nft-sortbtn{position:relative;flex:none;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:var(--s1);border:1px solid var(--line);color:var(--am)}",
".tm-mw .nft-hub .nft-sortbtn svg{width:19px;height:19px;stroke-width:2}",
".tm-mw .nft-hub .nft-sortbtn select{position:absolute;inset:0;width:100%;height:100%;opacity:0;font-size:16px;cursor:pointer}",
".tm-mw .nft-hub .nft-network-row{display:flex;gap:8px;overflow-x:auto;padding:0 16px 4px;margin:0 0 14px;scrollbar-width:none}",
".tm-mw .nft-hub .nft-network-row::-webkit-scrollbar{display:none}",
".tm-mw .nft-hub .nft-network-chip{flex:none;padding:7px 13px;border-radius:999px;font-size:12px;font-weight:700;background:transparent;border:1px solid var(--line);color:var(--mut);white-space:nowrap}",
".tm-mw .nft-hub .nft-network-chip.active{background:var(--txt);color:var(--bg);border-color:var(--txt)}",
".tm-mw .nft-hub .nft-section-head{padding:0 16px;margin:0 0 10px;display:flex;align-items:baseline;justify-content:space-between}",
".tm-mw .nft-hub .nft-section-head h2{font-size:15px}",
".tm-mw .nft-hub .nft-section-head small{color:var(--mut);font-size:11.5px}",
".tm-mw .nft-hub .nft-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:0 16px}",
".tm-mw .nft-hub .nft-card{border-radius:14px;box-shadow:none}",
".tm-mw .nft-hub .nft-art{margin:6px 6px 0;border-radius:10px}",
".tm-mw .nft-hub .nft-card-body{padding:8px 8px 9px}",
".tm-mw .nft-hub .nft-card-body h3{font-size:11.5px;line-height:1.25;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-family:'Hanken Grotesk',sans-serif;font-weight:700}",
".tm-mw .nft-hub .nft-price-row{margin-top:4px;gap:4px}",
".tm-mw .nft-hub .nft-price-row b{font-size:11.5px;white-space:nowrap}",
".tm-mw .nft-hub .nft-change{display:none}",
".tm-mw .nft-hub .nft-stats{margin-top:5px;gap:6px}",
".tm-mw .nft-hub .nft-stats>div:nth-child(2){display:none}",
".tm-mw .nft-hub .nft-stats small{font-size:9px}",
".tm-mw .nft-hub .nft-stats b{font-size:10.5px}",
".tm-mw .nft-hub .nft-view{display:inline-block;margin-top:6px;font-size:10px;font-weight:700;color:var(--am)}",
".tm-mw .nft-hub .nft-fav{width:26px;height:26px;font-size:13px}",
".tm-mw .nft-hub .nft-footnote{margin:16px 16px 0;font-size:11px;color:var(--mut)}",
"@media(min-width:760px){.tm-mw .nft-hub .nft-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}}"
