PG.profile=function(){var m=st.me,sell=st.mode==="Seller";
 return '<header class="ph"><button class="bk2" data-back aria-label="Back">'+ic("left")+'</button><span style="flex:1"></span><div class="rts"><button class="rt" data-pg="support" aria-label="Support">'+ic("headset")+'</button><button class="rt" data-act="uc" data-arg="My info" aria-label="User Center">'+ic("settings")+'</button></div></header><div class="pbody">'+
 '<div class="pt-hero"><div class="pt-av">'+(m.photo?'<img alt="" src="'+esc(m.photo)+'">':'<span class="pt-ti">Ti</span>')+'</div><div class="pt-id"><h1>'+esc(m.nick)+'</h1><div class="pt-uid">UID: '+m.uid+'<button data-act="copy" data-arg="'+m.uid+'" aria-label="Copy UID">'+ic("copy","width:20px;height:20px")+'</button></div><div class="pt-pills"><button class="pt-ok" data-pg="kycinfo">'+PT_SHIELD_G+'Lv.'+m.lvl+' verified</button><button class="pt-pill" data-pg="level">'+(sell?"Alpha":"Clients")+ic("chev","width:14px;height:14px")+'</button></div></div></div>'+
 '<div class="pt-card"><div class="pt-top"><span class="pt-sh">'+PT_SHIELD+'</span><span class="pt-vr"></span><div class="pt-tx"><h3>'+(sell?"Build your Alpha profile":"Build your client profile")+'</h3><p>'+(sell?"Complete identity verification to unlock higher offer limits and the verified badge.":"Complete identity verification to build trust with counterparties and strengthen the profile.")+'</p></div></div><div class="pt-prog"><div class="pt-bar"><i style="width:25%"></i></div><b>25%</b></div><div class="pt-meta"><small>Verification: 1 of 4 steps</small><button data-pg="level">'+(sell?"Alpha benefits":"Trust & verification")+' →</button></div><button class="pt-cta" data-pc="kyc">Verify now</button></div>'+
 '<div class="pcards"><button class="pc" data-f="Card">'+ic("card")+'<span>TradeMate Card<small>Join waitlist</small></span></button><button class="pc" data-f="Rewards">'+ic("gift")+'<span>Rewards Hub<small>Check now</small></span></button><button class="pc" data-f="'+("Contracts")+'">'+ic("box")+'<span>'+("Contracts")+'<small>View all</small></span></button><button class="pc" data-f="Referral">'+ic("users")+'<span>Invite Friends<small>Invite now</small></span></button></div>'+
 '<div class="sec" style="padding-top:22px">RECENTLY USED</div><div class="grid" style="padding-top:2px">'+st.recent.filter(function(n){return n!=="More"&&(sell||n!=="Add Contract")}).map(function(n){var o=FG.reduce(function(a,g){return a.concat(g[1])},[]).filter(function(x){return x[0]===n})[0]||["","more"];return '<button class="opt" data-f="'+n+'" style="--h:'+HUE[n]+'"><span class="tile">'+ic(o[1])+'</span><span class="opt-label">'+n+'</span></button>'}).join("")+'</div>'+
 '<div style="text-align:center;padding:18px"><button class="btn o" data-f="More">All Services</button></div>'+
 '</div><div class="pfoot"><button class="lr" style="justify-content:center;border:0;font-size:15px" data-act="mode"><span class="t" style="flex:none">'+(sell?"Clients":"Alpha")+' mode</span>'+ic("swap","width:16px;height:16px")+'</button><span style="width:1px;background:var(--line)"></span><button class="lr" style="justify-content:center;border:0;font-size:15px" data-pg="about"><span class="t" style="flex:none">About us</span>'+ic("chev","width:16px;height:16px")+'</button></div>'};
PG.uc=function(){var m=st.me,P=st.prefs,tab=st.uc,L=st.links||{},sell=st.mode==="Seller";
 var info=lr("person","Profile picture","",'data-pg="avatar"')+lr("id","Nickname",esc(m.nick),'data-pg="nick"')+'<button class="lr" data-act="copy" data-arg="'+m.uid+'"><span class="lic">'+ic("id")+'</span><span class="t">UID</span><em>'+m.uid+ic("copy","width:16px;height:16px")+'</em></button>'+lr("shield","Identity verification","Lv."+m.lvl,'data-pg="kycinfo"')+(sell?lr("subacct","Organization",st.org?(st.org.status==="active"?"Verified":"Pending verification"):"Manage your organization",'data-pg="subacct"'):"")+lr("lock","Security","",'data-pg="security"')+(sell?lr("trophy","Alpha level","Starter",'data-pg="level"'):"")+lr("percent","My fee rates","",'data-pg="fees"')+lr("doc","Additional verification","0 cases",'data-pg="addverif"')+lr("at","Link account",(L.telegram?"Telegram ":"")+(L.x?"X":"")||"",'data-pg="link"')+lr("affiliate","Affiliate’s community",st.joinedAff?"Joined":"",'data-pg="affcomm"')+lr("users","Join our community","",'data-pg="community"');
 var pref='<div class="lr" style="cursor:default"><span class="lic">'+ic("moon")+'</span><span class="t">Theme</span><button data-pg="theme"><em>'+(TM_THEMES[st.theme]||TM_THEMES.dark).label+ic("chev","width:16px;height:16px")+'</em></button></div>'+lr("globe","Language",st.lang||"English",'data-pg="lang"')+
  '<label class="lr"><span class="lic">'+ic("earn")+'</span><span class="t">Display currency</span><select data-pref="cur" style="background:none;border:0;font-weight:800;color:var(--mut)">'+["NGN","USD","EUR","GBP","GHS","KES"].map(function(c){return '<option'+(P.cur===c?" selected":"")+'>'+c+'</option>'}).join("")+'</select></label>'+
  '<label class="lr"><span class="lic">'+ic("mkts")+'</span><span class="t">Default market</span><select data-pref="market" style="background:none;border:0;font-weight:800;color:var(--mut)">'+ORD.map(function(c){return '<option value="'+c+'"'+(P.market===c?" selected":"")+'>'+mkL(c)+'</option>'}).join("")+'</select></label>'+
  '<div class="sec">NOTIFICATIONS</div>'+[["orders","Contract updates"],["p2p","P2P activity"],["promos","Promotions"],["news","Announcements"]].map(function(x){return '<div class="lr"><span class="t">'+x[1]+'</span>'+sw(P[x[0]],x[0])+'</div>'}).join("")+'<div class="lr"><span class="t">Hide balances by default</span>'+sw(st.hide,"hideb")+'</div>';
 var gen=lr("info","About us","",'data-pg="about"')+lr("doc","Terms of service","",'data-pg="info" data-arg="terms"')+lr("shield","Privacy policy","",'data-pg="info" data-arg="privacy"')+lr("cookie","Cookie policy","",'data-pg="info" data-arg="cookies"')+lr("help","Help Center","",'data-pg="help"')+lr("feedback","Feedback Hub","",'data-pg="feedback"')+lr("trophy","Rate TradeMate","",'data-toast="Thank you! Rating opens in the app store."')+lr("bolt","Clear cache","",'data-toast="Cache cleared"')+'<div class="lr" style="cursor:default"><span class="t">Version</span><em>1.0.0</em></div>';
 return '<header class="ph uc-hd"><button class="bk2" data-back aria-label="Back">'+ic("left")+'</button><h2>User Center</h2><div class="rts"><button class="rt" data-pg="theme" aria-label="Theme">'+ic("moon")+'</button><button class="rt" data-pg="lang" aria-label="Language">'+ic("globe")+'</button></div></header>'+
 '<div class="uc-tabs">'+["My info","Preference","General"].map(function(t){return '<button class="'+(tab===t?"on":"")+'" data-act="uc" data-arg="'+t+'">'+t+'</button>'}).join("")+'</div>'+(tab==="My info"?'<div class="uc-card"><div class="uc-av">'+(m.photo?'<img alt="" src="'+esc(m.photo)+'">':PT_PERSON)+'</div><div class="uc-id"><h1>'+esc(m.nick)+PT_BADGE+'</h1><button class="uc-sec" data-pg="security">Security level: <b>High</b>'+PT_BARS+'</button><div class="uc-reg">'+ic("globe","width:20px;height:20px")+'Region: Global</div></div></div>':'')+(tab==="My info"?info:tab==="Preference"?pref:gen)+'<div style="padding:22px 16px"><button class="btn o wide" data-pg="logout">Log Out</button></div>'};
var _pa=act;act=function(n,a,el){if(n==="pref"&&a==="hideb"){st.hide=!st.hide;draw();return}_pa(n,a,el)};
PG.avatar=function(){return hdr("Profile picture")+'<div style="display:grid;justify-items:center;gap:14px;padding:10px 16px 18px"><div style="display:flex;gap:10px"><label class="btn sm" style="position:relative;cursor:pointer;overflow:hidden">'+ic("upload","width:16px;height:16px")+(st.me.photo?"Change photo":"Upload photo")+'<input id="photoin" type="file" accept="image/*" aria-label="Upload profile photo" style="position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;font-size:0"></label>'+(st.me.photo?'<button class="btn sm o" data-act="rmphoto">Remove</button>':'')+'</div></div><div class="sec">OR PICK AN AVATAR</div><div class="avgrid">'+AVC.map(function(c,i){return '<button class="'+(st.me.av===i?"on":"")+'" data-act="avatar" data-arg="'+i+'" style="background:'+c+'" aria-label="Avatar '+(i+1)+'">'+esc(st.me.nick.charAt(0))+'</button>'}).join("")+'<button class="'+(st.me.av===7?"on":"")+'" data-act="avatar" data-arg="7" style="background:#0d1319;border:1.5px solid var(--line)" aria-label="Logo avatar"><img src="'+LOGO+'" style="width:64%" alt=""></button></div><div style="padding:20px 16px"><button class="btn wide" data-back>Done</button></div><p class="fine">Your photo is cropped to a square and kept on this device in the preview.</p>'};
PG.nick=function(){return hdr("Nickname")+'<div class="fs" style="padding:14px 16px"><label class="fld"><span>Nickname</span><input id="nick" value="'+esc(st.me.nick)+'" maxlength="24"></label><p class="fine" style="padding:0">Your nickname is shown to clients and Alpha members.</p><button class="btn wide" data-act="savenick">Save</button></div>'};
/* ===== Identity verification: one connected flow (hub > 3 steps > review > submitted) ===== */
function idvS(){if(!st.idv)st.idv={d:{},ok:[0,0,0],sub:0,agree:0,pv:{}};return st.idv}
function idvSteps(){return [
 {i:"person",t:"Personal Information",s:"Provide your basic details (name, date of birth, etc).",c:"var(--am)",tip:["Use your name exactly as it appears on your ID.","Your details are used for verification only."],f:[T("kn","Full name","As shown on your ID",1),D(T("kd","Date of birth","DD / MM / YYYY",1),T("kp","Phone number","e.g. +234 801 234 5678",1,"tel")),S("kc","Country of residence",CTRY,1),T("ka","Home address","Street and number",1),T("kcity","City","",1)]},
 {i:"id",t:"Identity Document",s:"Upload a valid government ID (e.g. National ID, Passport, Driver’s License).",c:"var(--in,#8b7bff)",tip:["Place the ID on a flat, well-lit surface.","All four corners and every detail must be visible.","No glare, blur or cropped edges."],f:[S("kt","ID type","National ID card|Passport|Driver’s licence|Residence permit|Voter’s card",1),T("ki","ID number","",1),["U2","kf","Front of ID",1,"gal"],["U2","kb","Back of ID (if it has one)",0,"gal"]]},
 {i:"camera",t:"Live Selfie",s:"Take a clear selfie to confirm it’s you.",c:"var(--co)",tip:["Face the camera in good lighting.","Remove hats, sunglasses or masks.","Hold your ID next to your face if you can."],f:[["U2","ks","Your selfie",1,"cam"]]}]}
function idvMiss(n){var s=idvSteps()[n],d=idvS().d,m=[];flat(s.f).forEach(function(f){var req=f[0]==="U2"?f[3]:(f[0]==="s"||f[0]==="t")?f[4]:0;if(!req)return;var v=d[f[1]];if(!v||(/^Other/.test(v)&&!(d[f[1]+"_o"]||"").trim()))m.push(f[2])});return m}
function idvDone(){var v=idvS();if((st.me.lvl||1)>=2)return 3;return v.sub?3:v.ok.reduce(function(a,b){return a+b},0)}
function idvVerified(){return (st.me.lvl||1)>=2}
function idvFieldRow(f){if(f[0]==="U2"){var k=f[1],v=idvS().d[k]||"",pv=idvS().pv[k];return '<label class="idv-up'+(v?' has':'')+'"><span class="idv-upl">'+f[2]+(f[3]?' <b>*</b>':'')+'</span><span class="idv-th">'+(pv?'<img alt="" src="'+pv+'">':ic(f[4]==="cam"?"camera":"upload"))+'</span><i>'+esc(v||(f[4]==="cam"?"Tap to take a selfie":"Tap to choose a file"))+'</i><small>'+(f[4]==="cam"?"JPG or PNG · front camera opens on your phone":"JPG, PNG or PDF · up to 5 MB")+'</small><input type="file" hidden data-up="'+k+'" accept="'+(f[4]==="cam"?"image/*":"image/*,application/pdf")+'"'+(f[4]==="cam"?' capture="user"':'')+'></label>'}return fieldHTML(f)}
var IDV_SHIELD='<svg viewBox="0 0 64 64" aria-hidden="true"><path class="s1" d="M32 5l21 8v16c0 14-9 24-21 29C20 53 11 43 11 29V13z"/><circle class="s2" cx="32" cy="26" r="6.5"/><path class="s2" d="M20 43c1.5-6.5 7-9.5 12-9.5s10.5 3 12 9.5"/></svg>';
function idvArt(cls){return '<div class="'+cls+'" aria-hidden="true">'+IDV_SHIELD+'<span class="idv-chk">'+ic("check")+'</span></div>'}
function idvHead(title,right,hub){return '<header class="ph idv-ph'+(hub?" hub":"")+'"><button class="bk2" data-back aria-label="Back">'+ic("left")+'</button><h2>'+(hub?"":"Verification")+'</h2>'+(right||'')+'</header>'}
function idvBell(){var u=unread();return '<button class="rt sx-bell" data-pg="notif" aria-label="Notifications">'+ic("bell")+(u?'<em class="sx-badge">'+(u>99?"99+":u)+'</em>':"")+'</button>'}
function idvNextStep(){var v=idvS();for(var i=0;i<3;i++)if(!v.ok[i])return i;return -1}
PG.kycinfo=function(){
 var v=idvS(),ver=idvVerified(),n=idvDone(),sub=v.sub&&!ver,ST=idvSteps(),nx=idvNextStep();
 var status=ver?"Verified":sub?"Under review":n?"In progress":"Not Verified",cls=ver?" ok":sub?" rv":n?" ip":"";
 var msg=ver?"Your identity is verified. Thank you!":sub?"We’ll notify you as soon as it has been reviewed.":n?(3-n)+" more step"+(3-n>1?"s":"")+" to go. Pick up where you left off.":"Complete the steps below to get verified.";
 var BEN=[['<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="13" width="4" height="7.5" rx="1.4"/><rect x="10" y="8.5" width="4" height="12" rx="1.4"/><rect x="16.5" y="3.5" width="4" height="17" rx="1.4"/></svg>',"Higher","trade limits","var(--am)"],[ic("shield"),"Build","trust","var(--in,#8b7bff)"],[ic("bolt"),"Unlock","Alpha levels","var(--am)"],['<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.6l2.5 5.2 5.7.8-4.1 4 1 5.7-5.1-2.7-5.1 2.7 1-5.7-4.1-4 5.7-.8z"/></svg>',"Priority","support","var(--am)"]];
 var cta=(ver||sub)?'':'<div class="idv-cta"><button class="idv-btn" data-pc="idvGo" data-arg="next">'+(nx<0?"Review & submit":n?"Continue Verification":"Start Verification")+'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></div>';
 return idvHead("Identity Verification",idvBell(),1)+'<div class="idv">'+
 '<div class="idv-intro">'+idvArt("idv-art")+'<div class="idv-it"><div class="idv-eyebrow">Verification</div></div></div>'+
 '<section class="idv-st'+cls+'">'+idvArt("idv-sh")+'<div class="idv-stx"><h2>Verification Status</h2><span class="idv-pill">'+(ver?ic("check"):"")+status+'</span><p>'+msg+'</p></div></section>'+
 '<ul class="idv-ben">'+BEN.map(function(b){return '<li style="--c:'+b[3]+'"><i>'+b[0]+'</i><span>'+b[1]+'<br>'+b[2]+'</span></li>'}).join("")+'</ul>'+
 '<div class="idv-sec"><h3><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6h11M9 12h11M9 18h11"/><circle cx="4.6" cy="6" r="1.1"/><circle cx="4.6" cy="12" r="1.1"/><circle cx="4.6" cy="18" r="1.1"/></svg>Verification Steps</h3><b>'+n+' of 3 completed</b></div>'+
 '<ol class="idv-steps">'+ST.map(function(s,i){var d=ver||sub||v.ok[i];return '<li><button class="idv-step'+(d?' done':'')+'" '+((ver||sub)?'disabled':'data-pc="idvGo" data-arg="'+i+'"')+' style="--c:'+s.c+'"><span class="idv-ico">'+(d?ic("check"):ic(s.i))+'</span><span class="idv-tx"><b>'+(i+1)+'. '+s.t+'</b><small>'+s.s+'</small></span><span class="idv-go">'+(d&&!ver&&!sub?'<em>Edit</em>':'')+ic("chev")+'</span></button></li>'}).join("")+'</ol>'+cta+'</div>'};
PG.kycstep=function(i){
 i=+i||0;var v=idvS(),ST=idvSteps(),s=ST[i];st.fv=v.d;
 var seg='<div class="idv-seg" role="progressbar" aria-valuemin="1" aria-valuemax="3" aria-valuenow="'+(i+1)+'">'+ST.map(function(x,j){return '<i class="'+(v.ok[j]?'dn':j===i?'on':'')+'"></i>'}).join("")+'</div>';
 var rail='<aside class="idv-rail"><div class="idv-card"><h4>Your progress</h4><ol class="idv-vt">'+ST.map(function(x,j){return '<li class="'+(j===i?'on':v.ok[j]?'dn':'')+'" style="--c:'+x.c+'"><button data-pc="idvJump" data-arg="'+j+'"><span>'+(v.ok[j]?ic("check"):j+1)+'</span><b>'+x.t+'</b></button></li>'}).join("")+'</ol></div><div class="idv-card idv-tips"><h4>'+ic("shield")+'Tips for a quick review</h4><ul>'+s.tip.map(function(t){return '<li>'+t+'</li>'}).join("")+'</ul></div></aside>';
 return idvHead(s.t)+'<div class="idv idv-flow">'+seg+'<div class="idv-grid"><div class="idv-main"><div class="idv-hero" style="--c:'+s.c+'"><span class="idv-ico big">'+ic(s.i)+'</span><div><small>Step '+(i+1)+' of 3</small><h1>'+s.t+'</h1><p>'+s.s+'</p></div></div>'+
 '<div class="idv-card idv-form"><div class="fs">'+s.f.map(idvFieldRow).join("")+'</div><div class="idv-tipsm"><b>'+ic("shield")+'Tips</b><ul>'+s.tip.map(function(t){return '<li>'+t+'</li>'}).join("")+'</ul></div></div>'+
 '<div class="idv-btns">'+(i>0?'<button class="idv-btn o" data-pc="idvPrev" data-arg="'+i+'">Back</button>':'')+'<button class="idv-btn" data-pc="idvNext" data-arg="'+i+'">'+(i===2?"Save & Review":"Save & Continue")+'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></div></div>'+rail+'</div></div>'};
PG.kycreview=function(){
 var v=idvS(),ST=idvSteps(),all=v.ok[0]&&v.ok[1]&&v.ok[2];
 var cards=ST.map(function(s,i){var rows=flat(s.f).map(function(f){var val=v.d[f[1]]||"";if(f[0]==="U2")val=val?"Uploaded · "+val:"";else if(/^Other/.test(val)&&v.d[f[1]+"_o"])val=v.d[f[1]+"_o"];return val?'<div><span>'+f[2].replace(" (if it has one)","")+'</span><b>'+esc(val)+'</b></div>':""}).join("");
  return '<section class="idv-card idv-rv" style="--c:'+s.c+'"><div class="idv-rvh"><span class="idv-ico">'+ic(v.ok[i]?"check":s.i)+'</span><h3>'+(i+1)+'. '+s.t+'</h3><button class="idv-ed" data-pc="idvGo" data-arg="'+i+'">'+(v.ok[i]?"Edit":"Complete")+'</button></div>'+(v.ok[i]?'<div class="idv-rows">'+rows+'</div>':'<p class="idv-warn">This step isn’t finished yet.</p>')+'</section>'}).join("");
 return idvHead("Review & Submit")+'<div class="idv idv-flow"><div class="idv-seg"><i class="dn"></i><i class="dn"></i><i class="dn"></i></div><div class="idv-hero" style="--c:var(--am)"><span class="idv-ico big">'+ic("shield")+'</span><div><small>Final step</small><h1>Review your details</h1><p>Check everything is correct before you submit it for review.</p></div></div><div class="idv-revw">'+cards+'</div>'+
 '<button class="idv-agree" role="checkbox" aria-checked="'+(v.agree?"true":"false")+'" data-pc="idvAgree"><span class="idv-box">'+(v.agree?ic("check"):"")+'</span><span>I confirm the information and documents are mine and accurate.</span></button>'+
 '<div class="idv-btns"><button class="idv-btn o" data-pc="idvPrev" data-arg="3">Back</button><button class="idv-btn'+((all&&v.agree)?'':' off')+'" data-pc="idvSubmit">Submit for review<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></div></div>'};
PG.kycdone=function(){return idvHead("Identity Verification")+'<div class="idv idv-ok"><div class="idv-okart">'+idvArt("idv-art lgx")+'</div><h1>Verification submitted</h1><p>We’ll notify you when it has been reviewed. This usually takes a short while.</p><ul class="idv-next"><li><span>'+ic("check")+'</span>Details received</li><li><span>'+ic("clock")+'</span>Review in progress</li><li><span>'+ic("bolt")+'</span>Higher limits unlocked once approved</li></ul><button class="idv-btn" data-closeall>Done</button></div>'};
function idvPage(id,a){var top=st.stack[st.stack.length-1];if(top&&top.id==="kycinfo"){pg(id,a)}else{st.stack[st.stack.length-1]={id:id,a:a};drawPage()}var e=document.querySelector(".pgs");if(e)e.scrollTop=0}
