 var rows=AL_LV.map(function(x,i){var on=i===cur;return '<li class="al-row'+(on?' on':' lock')+'" style="--c:'+x[2]+'"><span class="al-node">'+(on?'':ic("lock"))+'</span><div class="al-card">'+alShield(x[1])+'<div class="al-tx"><b>'+x[0]+'</b><small>'+x[3]+'</small>'+(x[4]?'<small>'+x[4]+'</small>':'')+'</div>'+(on?'<span class="al-pill">Current level</span>':'')+'</div></li>'}).join("");
