PG.fees=function(){return hdr("My fee rates")+'<div class="card"><h3>Fees</h3><p>Final fee rates will be published before launch. Nothing is charged in the preview.</p></div>'+[["Market contract","Not set"],["P2P advertisements","Not set"],["Promotion","Not set"],["Contract fees","Not set"]].map(function(x){return '<div class="lr" style="cursor:default"><span class="t">'+x[0]+'</span><em>'+x[1]+'</em></div>'}).join("")};
