hresHTML=function(){var q=(st.hq||"").toLowerCase(),l=FAQ.filter(function(f){return !q||f[0].toLowerCase().indexOf(q)>=0||f[1].toLowerCase().indexOf(q)>=0});
 return l.length?l.map(function(f){var k="f"+f[0],o=st.open[k];return '<div class="hc-q'+(o?' on':'')+'"><button type="button" data-act="faq" data-arg="'+esc(k)+'" aria-expanded="'+(o?'true':'false')+'"><span>'+f[0]+'</span>'+HC_CHEV+'</button>'+(o?'<p>'+f[1]+'</p>':'')+'</div>'}).join(""):'<div class="hc-empty"><b>No answers found</b>Open a ticket and we will help.</div>'};
