PC.paymentsent=function(id){var ref=window.prompt("Optional payment reference (do not enter banking passwords or PINs):")||"";api("POST","/p2p/orders/"+encodeURIComponent(id)+"/payment-sent",{reference:ref}).then(function(){p2pPrivate.updated=0;return loadP2PPrivate(true)}).then(drawPage).catch(fail)};
PC.confirmreceipt=function(id){if(!window.confirm("Confirm that you have received the buyer’s payment? Only confirm after checking your account."))return;api("POST","/p2p/orders/"+encodeURIComponent(id)+"/confirm-receipt",{}).then(function(){p2pPrivate.updated=0;return loadP2PPrivate(true)}).then(drawPage).catch(fail)};
PC.dispute=function(id){var reason=window.prompt("Describe the issue (at least 5 characters):");if(!reason||reason.trim().length<5)return toast("Please provide a dispute reason.");api("POST","/p2p/orders/"+encodeURIComponent(id)+"/dispute",{reason:reason.trim()}).then(function(){p2pPrivate.updated=0;return loadP2PPrivate(true)}).then(drawPage).catch(fail)};
PC.ot=function(a){st.ot=a;drawPage()};
PG.myads=function(){loadP2PPrivate();var rows=p2pPrivate.ads;return hdr("My advertisements")+(p2pPrivate.loading?'<div class="empty">Loading your advertisements…</div>':p2pPrivate.error?'<div class="empty"><b>Could not load advertisements</b>'+esc(p2pPrivate.error)+'</div>':!rows.length?'<div class="empty"><b>No advertisements yet</b>Publish a P2P offer and it will appear here.</div>':rows.map(function(x){return '<div class="ad"><div class="who"><b>'+esc(x.side.toUpperCase())+' · '+esc(x.asset_code)+' / '+esc(x.fiat_code)+'</b><small>'+esc(x.status)+' · '+fmtT(x.created_at)+'</small></div><div class="pr">'+p2pMoney(x.price,x.fiat_code)+'</div><div class="kv">Available<b>'+esc(x.remaining_quantity)+' '+esc(x.asset_code)+'</b><br>Limits<b>'+p2pMoney(x.min_fiat_amount,x.fiat_code)+' – '+p2pMoney(x.max_fiat_amount,x.fiat_code)+'</b></div>'+(x.status==="open"||x.status==="partially_filled"?'<button class="btn sm o" data-pc="cancelad" data-arg="'+esc(x.id)+'">Cancel offer</button>':'')+'</div>'}).join(""))+'<button class="fab-plus" data-f="Create order" data-pre="P2P" aria-label="Post an advertisement"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/></svg></button>'};
PC.cancelad=function(id){if(!CONNECTED)return;api("DELETE","/p2p/ads/"+encodeURIComponent(id)).then(function(){p2pPrivate.updated=0;return loadP2PPrivate(true)}).then(drawPage).catch(fail)};
PG.p2porder=function(id){var a=p2pCache.book.find(function(x){return x.id===id});if(!a)return hdr("P2P offer")+'<div class="empty">This offer is no longer available. Refresh the P2P market.</div>';var side=a.side==="sell"?"Buy":"Sell",qty=Number(a.quantity),price=Number(a.price),min=Number(a.min_fiat_amount),max=Number(a.max_fiat_amount);return hdr(side+" "+a.asset_code)+'<div class="card"><b>'+esc(a.asset_code)+' / '+esc(a.fiat_code)+'</b><div style="font:800 26px Bricolage Grotesque,sans-serif;margin:12px 0">'+p2pMoney(price,a.fiat_code)+' <small style="font-size:13px;color:var(--mut)">per '+esc(a.asset_code)+'</small></div><p>Limits '+p2pMoney(min,a.fiat_code)+' – '+p2pMoney(max,a.fiat_code)+' · Available '+fx2(qty,6)+' '+esc(a.asset_code)+'</p><p class="fine">Accepted payment methods: '+(Array.isArray(a.payment_methods)&&a.payment_methods.length?a.payment_methods.map(function(method){return esc(method)}).join(' · '):'Not specified')+'</p></div><div class="fs" style="padding:4px 16px"><label class="fld"><span>Fiat amount ('+esc(a.fiat_code)+')</span><input id="poa" data-k="poa" inputmode="decimal" placeholder="Enter amount" value="'+esc(fv("poa"))+'"></label><div class="card" style="margin:0"><small style="color:var(--mut)">ESTIMATED CRYPTO</small><div id="poout" style="font:800 22px Bricolage Grotesque,sans-serif;margin-top:4px">0 '+esc(a.asset_code)+'</div></div><p class="fine">The order is recorded in TradeMate. Payment happens directly between the buyer and seller; TradeMate does not hold funds or provide escrow.</p><button class="btn wide '+(side==="Sell"?"sell":"buy")+'" data-pc="place" data-arg="'+esc(id)+'">Create '+side.toLowerCase()+' order</button></div>'};
document.addEventListener("input",function(e){if(e.target.id==="poa"){var id=st.stack[st.stack.length-1]&&st.stack[st.stack.length-1].a,a=p2pCache.book.find(function(x){return x.id===id}),v=Number(e.target.value),o=$("poout");if(o&&a)o.textContent=(v>0?fx2(v/Number(a.price),6):"0")+" "+a.asset_code}});
PC.place=function(id){var a=p2pCache.book.find(function(x){return x.id===id}),v=Number(st.fv.poa);if(!a)return fail(new Error("Offer not found. Refresh the P2P market."));if(!(v>=Number(a.min_fiat_amount)&&v<=Number(a.max_fiat_amount)))return fail(new Error("Enter an amount within this offer's limits."));api("POST","/p2p/orders",{adId:id,fiatAmount:v}).then(function(){st.fv={};p2pPrivate.updated=0;return loadP2PPrivate(true)}).then(function(){toast("P2P order created. Check Orders for the next step.");pg("orders")}).catch(fail)};
