function fv(k){return st.fv[k]==null?"":st.fv[k]}
function oth(k){return '<input class="oth" data-k="'+k+'_o" placeholder="Please specify" value="'+esc(fv(k+"_o"))+'" style="display:'+(/^Other/.test(fv(k))?"block":"none")+'">'}
function lab(l,req){return '<span>'+l+(req?' <b>*</b>':'')+'</span>'}
function Ftext(k,l,ph,req,mode){return '<label class="fld">'+lab(l,req)+'<input data-k="'+k+'" value="'+esc(fv(k))+'" placeholder="'+esc(ph||"")+'"'+(mode?' inputmode="'+mode+'"':'')+'></label>'}
function Fpassword(k,l,ph,req,autocomplete){return '<label class="fld">'+lab(l,req)+'<input id="'+k+'" type="password" placeholder="'+esc(ph||"") +'" autocomplete="'+(autocomplete||"new-password")+'"></label>'}
function Farea(k,l,ph,req){return '<label class="fld">'+lab(l,req)+'<textarea data-k="'+k+'" placeholder="'+esc(ph||"")+'">'+esc(fv(k))+'</textarea></label>'}
function opts(list,cur,all){return '<option value=""'+(cur?"":" selected")+' disabled>Select…</option>'+list.split("|").map(function(x){return '<option'+(cur===x?" selected":"")+'>'+x+'</option>'}).join("")}
function Fsel(k,l,list,req){return '<label class="fld sl">'+lab(l,req)+'<select class="so" data-k="'+k+'">'+opts(list,fv(k))+'</select>'+oth(k)+'</label>'}
function Fselg(k,l,g,req){var cur=fv(k);return '<label class="fld sl">'+lab(l,req)+'<select class="so" data-k="'+k+'"><option value=""'+(cur?"":" selected")+' disabled>Select…</option>'+G[g].map(function(x){return '<optgroup label="'+x[0]+'">'+x[1].split("|").map(function(o){return '<option'+(cur===o?" selected":"")+'>'+o+'</option>'}).join("")+'</optgroup>'}).join("")+'</select>'+oth(k)+'</label>'}
function Fprice(k,l,req){var c=fv(k+"_c")||"NGN";return '<label class="fld pr2">'+lab(l,req)+'<select class="so" data-k="'+k+'_c" aria-label="Currency">'+CURS.split("|").map(function(x){return '<option'+(c===x?" selected":"")+'>'+x+'</option>'}).join("")+'</select><input data-k="'+k+'" inputmode="decimal" placeholder="0.00" value="'+esc(fv(k))+'"><input class="oth" data-k="'+k+'_c_o" placeholder="Currency code" value="'+esc(fv(k+"_c_o"))+'" style="grid-column:1/-1;display:'+(/^Other/.test(c)?"block":"none")+'"></label>'}
function Fchips(k,l,list){var a=fv(k)||[];return '<div><div class="sec" style="padding:0 2px 8px">'+l+'</div><div class="chips2">'+list.split("|").map(function(x){return '<label class="chk"><input type="checkbox" data-ck="'+k+'" value="'+x+'"'+(a.indexOf(x)>=0?" checked":"")+'>'+x+'</label>'}).join("")+'</div></div>'}
function Fup(k,l){return '<label class="fld" style="padding:18px 16px;text-align:center;border-style:dashed;cursor:pointer"><span style="position:static;display:block;margin-bottom:6px">'+l+'</span>'+ic("upload","color:var(--am)")+'<i style="display:block;font-style:normal;font-weight:700;margin-top:4px">'+esc(fv(k)||"Tap to choose a file")+'</i><input type="file" hidden data-up="'+k+'" multiple></label>'}
