function cfHead(t,p){return '<div class="cf-head"><div class="cf-ht"><h1>'+t+'</h1><p>'+p+'</p></div>'+CF_ART+'</div>'}
PG.listpick=function(){return cfTop()+'<div class="cf cf2 cf3"><div class="cf2-hero"><div class="cf2-ht"><h1>Create a contract</h1><p>Choose the type of contract you want to create.</p></div>'+CF_ART+'</div><div class="cf3-types">'+CT.map(function(t){return '<button class="ctype" data-pc="wz" data-arg="c:'+t[0]+'" style="--h:'+t[3]+'"><span class="tile" style="--h:'+t[3]+'">'+ic(t[1])+'</span><span><b>'+mkL(t[0])+'</b><small>'+t[2]+'</small></span><em class="cf3-go">'+CF2_CHEV+'</em></button>'}).join("")+'</div><div class="cf2-note">'+RW_INFO+'<span>Professional Services and B2B offers can be submitted for review. All other contract categories are saved on this device until their publishing workflows are released. P2P remains a separate flow.</span></div></div>'};
PC.wz=function(a){st.fv={};st.cw={id:a,step:0,done:false};st.stack.pop();pg("wiz")};
PG.wiz=function(){var w=st.cw,c=wzCfg(w.id),n=c.steps.length,s=c.steps[w.step],last=w.step===n-1;
 if(w.done)return hdr(c.title)+'<div class="done"><div class="ok">'+ic("check")+'</div><h2>'+c.doneT+'</h2><p style="color:var(--mut);font-weight:600;margin:10px 0 24px">'+c.doneS+'</p><button class="btn wide" data-closeall>Done</button></div>';
 var isC=c.submit==="Add Contract";
 var steps='<ol class="cf2-steps" style="grid-template-columns:repeat('+n+',minmax(0,1fr))">'+c.steps.map(function(x,i){return '<li class="'+(i===w.step?"on":i<w.step?"dn":"")+'"><i>'+(i<w.step?CF2_CHK:i+1)+'</i><span>'+x.n+'</span></li>'}).join("")+'</ol>';
 var body;if(last){var rows="";c.steps.slice(0,-1).forEach(function(x){flat(x.f).forEach(function(f){if(f[0]==="u")return;var v=fvalue(f);if(v)rows+='<div><span>'+f[2]+'</span><b>'+esc(v)+'</b></div>'})});body='<div class="rv">'+(rows||'<div><span>Nothing filled in yet</span><b></b></div>')+'</div><p class="fine" style="padding:0">Check everything before you continue. You can go back to change anything.</p>'}
 else body='<div class="fs">'+s.f.map(fieldHTML).join("")+'</div>';
 var pills=isC?'<div class="cf-intro">'+c.intro.map(function(i){return '<span>'+ic(i[0])+i[1]+'</span>'}).join("")+'</div>':'';
 return cfTop()+'<div class="cf cf2 cf3"><div class="cf2-hero"><div class="cf2-ht"><h1>'+c.title+'</h1><p>'+c.intro.map(function(i){return i[1]}).join(" · ")+'</p></div>'+CF_ART+'</div>'+steps+'<div class="cf-form cf2-card cf3-card"><div class="cf3-sh"><h2>'+s.n+'</h2><small>Step '+(w.step+1)+' of '+n+'</small></div>'+body+'<div class="cf3-btns">'+(w.step>0?'<button class="cf2-send o" data-pc="wprev">Back</button>':'')+'<button class="cf2-send" data-pc="wnext"><span>'+(last?c.submit:"Continue")+'</span></button></div></div></div>'};
