".og-pill{display:inline-flex;align-items:center;gap:5px;margin-top:6px;padding:3px 9px;border-radius:999px;border:1px solid color-mix(in srgb,var(--am) 65%,transparent);background:color-mix(in srgb,var(--am) 8%,transparent);color:var(--am);font:700 11px 'Hanken Grotesk',sans-serif}.og-pill svg{width:10px;height:10px;stroke-width:3}.og-pill.bad{color:var(--dn);border-color:color-mix(in srgb,var(--dn) 60%,transparent);background:color-mix(in srgb,var(--dn) 8%,transparent)}",
".og-meta{margin:7px 0 0;color:var(--txt);font-size:12px;font-weight:700}.og-meta i{font-style:normal;color:var(--mut);margin:0 5px}.og-role{margin:2px 0 0;color:var(--mut);font-size:11.5px;font-weight:600}",
/* stepper */
".ogs{display:grid;grid-template-columns:repeat(4,1fr);margin-top:16px}",
".ogs-i{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center;font:600 11.5px 'Hanken Grotesk',sans-serif;color:var(--mut)}",
".ogs-i:before{content:'';position:absolute;top:12px;right:50%;width:100%;height:2px;background:var(--line)}.ogs-i:first-child:before{display:none}.ogs-i.ok:before,.ogs-i.now:before{background:var(--am)}",
".ogs-d{position:relative;z-index:1;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--s3);color:var(--mut);font:800 11.5px 'Hanken Grotesk',sans-serif}.ogs-d svg{width:13px;height:13px;stroke-width:2.6}",
".ogs-i.ok .ogs-d{background:var(--am);color:var(--ongrad,#1b1006)}.ogs-i.ok{color:var(--txt)}",
".ogs-i.now .ogs-d{background:var(--s1);border:2px solid var(--am);color:var(--am)}.ogs-i.now{color:var(--txt)}",
/* details */
".og-hd{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:4px}.og-hd h3{font:800 15px 'Bricolage Grotesque','Hanken Grotesk',sans-serif;letter-spacing:-.01em}",
".og-hd .og-pen{width:30px;height:30px;border-radius:9px;border:1px solid color-mix(in srgb,var(--am) 55%,transparent);color:var(--am);background:none;display:grid;place-items:center}.og-hd .og-pen svg{width:14px;height:14px}",
".og-hd .og-cnt{color:var(--mut);font-size:11px;font-weight:700}",
".og-r{display:flex;align-items:center;gap:12px;padding:9px 0;border-top:1px solid color-mix(in srgb,var(--line) 70%,transparent);font-size:13px}.og-r:first-of-type{border-top:0}",
".og-r>svg{flex:none;width:17px;height:17px;color:var(--am)}.og-r span{flex:1;min-width:0;color:var(--mut);font-weight:600}.og-r b{max-width:55%;text-align:right;font-weight:700;overflow-wrap:anywhere}",
/* documents */
".og-doc{display:flex;align-items:center;gap:10px;padding:8px 10px;margin-top:6px;border-radius:12px;background:var(--s2)}.og-doc:first-of-type{margin-top:0}",
