".og-doc>div{flex:1;min-width:0}.og-doc b{display:block;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.og-doc small{display:block;margin-top:1px;color:var(--mut);font-size:11px;font-weight:600}",
