;(function(){var e=document.createElement("style");e.id="pm-mock-css";e.textContent="\n.pm-card:first-child .pm-seg{display:none}\n.pm-rg{stroke:url(#pmrg);stroke-width:16;filter:drop-shadow(0 0 6px color-mix(in srgb,var(--am) 40%,transparent))}\n.pm-rt{stroke-width:16}\n.pm-card:first-child .pm-pill{padding:7px 8px 7px 14px;border-radius:999px;background:var(--s2);box-shadow:inset 0 0 0 1px var(--line);color:var(--txt)}\n.pm-card:first-child .pm-pill svg{color:var(--txt)}\n.pm-card:first-child .pm-val .pm-up{background:none;padding:0}\n.pm-card:first-child .pm-st small{position:relative;padding-left:9px}\n.pm-card:first-child .pm-st small i{position:absolute;left:0;top:.38em;margin:0}\n.pm-card:first-child .pm-st b{padding-left:9px}\n.pm-sd{filter:drop-shadow(0 0 5px var(--am))}\n.pm-sl{filter:drop-shadow(0 0 4px color-mix(in srgb,var(--am) 55%,transparent))}\n@container (max-width:479px){\n.pm-pb{grid-template-columns:18cqi minmax(0,1fr) minmax(0,1.25fr);grid-template-areas:\"r v s\" \"r p p\";gap:3cqi 2.5cqi;align-items:center}\n.pm-ring{width:18cqi;height:18cqi}.pm-ring b{font-size:5.4cqi}.pm-ring small{font-size:2.4cqi;line-height:1.15}\n.pm-val{padding-left:2.5cqi;border-left:1px solid var(--line)}\n.pm-val small{flex-wrap:wrap;font-size:2.8cqi;line-height:1.2}\n.pm-tt{display:none}\n.pm-val b{font-size:5.4cqi;margin:2px 0 4px;white-space:nowrap}\n.pm-up{font-size:2.9cqi}\n.pm-st{grid-template-columns:repeat(3,auto);justify-content:space-between;padding:0 0 0 2.5cqi;border-left:1px solid var(--line);align-self:center;gap:1.5cqi}\n.pm-st small{font-size:2.55cqi;line-height:1.25}\n.pm-st b{font-size:4.2cqi;margin-top:3px}\n.pm-sp{height:11cqi;margin-left:2.5cqi;width:calc(100% - 2.5cqi)}\n}\n.pm-card:nth-child(2) .pm-bal{color:var(--txt);background:var(--s2);box-shadow:inset 0 0 0 1px var(--line)}\n.pmx .pm-card:nth-child(2) .pm-bal b{color:var(--txt)}\nhtml[data-theme]:not([data-theme~=dark]) .pmx.pmx.pmx .pm-bal.pm-bal small,html[data-theme]:not([data-theme~=dark]) .pmx.pmx.pmx .pm-bal.pm-bal small button{color:var(--mut)!important}\n.pm-card:nth-child(2) .pm-bal .pm-up{background:color-mix(in srgb,var(--up) 14%,transparent);color:var(--up)}\n.pm-card:nth-child(2) .pm-tile>span{color:var(--txt)!important}\n.pm-doc{cursor:pointer}\n.pmd-ov{position:fixed;inset:0;z-index:60;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.55)}\n.pmd-sh{width:100%;max-width:520px;box-sizing:border-box;padding:18px 18px calc(18px + env(safe-area-inset-bottom,0px));border-radius:24px 24px 0 0;background:var(--s1);box-shadow:inset 0 0 0 1px var(--line);color:var(--txt);font-family:'Hanken Grotesk',system-ui,sans-serif}\n.pmd-top{display:flex;align-items:center;gap:12px}\n.pmd-top svg.f{width:34px;height:43px;flex:none;display:block}\n.pmd-top b{display:block;font:800 16px/1.25 'Bricolage Grotesque','Hanken Grotesk',sans-serif}\n.pmd-top small{color:var(--mut);font:600 12px 'Hanken Grotesk',sans-serif}\n.pmd-pv{margin:16px 0 0;padding:28px 14px;border-radius:14px;background:var(--s2);box-shadow:inset 0 0 0 1px var(--line);color:var(--mut);font:600 13px/1.4 'Hanken Grotesk',sans-serif;text-align:center}\n.pmd-tx{flex:1;min-width:0}\n.pmd-top .pmd-dl{flex:none;width:42px;height:42px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;cursor:pointer;background:var(--am);color:var(--ongrad,#1b1006);transition:filter .15s,transform .15s}\n.pmd-top .pmd-dl svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}\n.pmd-top .pmd-dl:hover{filter:brightness(1.08)}.pmd-top .pmd-dl:active{transform:scale(.94)}\n.pmd-top .pmd-dl:focus-visible{outline:2px solid var(--txt);outline-offset:2px}\n@media(min-width:600px){.pmd-ov{align-items:center}.pmd-sh{border-radius:24px}}\n";document.head.appendChild(e)})();
(function(){function close(){var o=document.getElementById("pmdov");if(o)o.remove()}
function open(d){close();var f=d.querySelector("svg.f"),t=d.querySelector("b"),s=d.querySelector("span"),sg=d.querySelector("em"),o=document.createElement("div");o.id="pmdov";o.className="pmd-ov";
o.innerHTML='<div class="pmd-sh" role="dialog" aria-label="Document"><div class="pmd-top">'+(f?f.outerHTML:"")+'<div class="pmd-tx"><b></b><small></small></div><button class="pmd-dl" type="button" data-act="pmdl" aria-label="Download document"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v11M7.5 10.5L12 15l4.5-4.5M5 19h14"/></svg></button></div><div class="pmd-pv">Document preview is not connected yet.</div></div>';
o.querySelector(".pmd-top b").textContent=t?t.textContent:"";o.querySelector(".pmd-top small").textContent=(s?s.textContent:"")+(sg?" \u00b7 Signed":"");document.body.appendChild(o)}
document.addEventListener("click",function(e){var t=e.target;if(!t||!t.closest)return;if(t.closest("[data-pmclose]")||t.id==="pmdov"){close();return}var d=t.closest(".pm-doc");if(d)open(d)});
document.addEventListener("keydown",function(e){if(e.key==="Escape"){if(document.getElementById("pmdov"))close();else{var al=document.getElementById("pmall");if(al)al.remove()}}else if((e.key==="Enter"||e.key===" ")&&e.target.classList&&e.target.classList.contains("pm-doc")){e.preventDefault();open(e.target)}})})();

;(function(){var e=document.createElement("style");e.id="pm-fix-css";e.textContent="\n.pmx>.pm-card:nth-child(-n+2){display:flex;flex-direction:column}\n.pmx>.pm-card:nth-child(-n+2)>.pm-pb,.pmx>.pm-card:nth-child(-n+2)>.pm-wb{flex:1 1 auto}\n.pm-sp{align-self:end}\n.pm-card:first-child .pm-st small{white-space:nowrap}\n@container (max-width:479px){\n.pm-pb{grid-template-columns:22cqi minmax(0,1fr) minmax(0,1.35fr);gap:3cqi 2cqi}\n.pm-ring{width:22cqi;height:22cqi}.pm-ring b{font-size:6cqi}.pm-ring small{font-size:2.6cqi}\n.pm-val{padding-left:2cqi}.pm-val b{font-size:4.9cqi}\n.pm-st{padding-left:2cqi;gap:1cqi}.pm-st small{font-size:2.45cqi}.pm-st b{font-size:4.2cqi}\n.pm-sp{margin-left:2cqi;width:calc(100% - 2cqi)}\n.pm-wb{grid-template-columns:minmax(0,1.15fr) repeat(2,minmax(0,1fr));grid-template-rows:1fr 1fr;gap:8px}\n.pm-bal{grid-column:1;grid-row:1/3;min-height:0;padding:9px 10px;display:flex;flex-direction:column;justify-content:center}\n.pm-bal img.w{display:none}\n.pmx .pm-bal b{font-size:5cqi;margin:3px 0 4px}\n.pm-bal small{font-size:2.8cqi;flex-wrap:wrap}\n.pm-bal .pm-up{align-self:flex-start;font-size:2.9cqi}\n.pm-tile{flex-direction:row;justify-content:flex-start;align-items:center;gap:6px;padding:0 2px;font-size:11px}\n.pm-tile>span{width:30px;height:30px;flex:none}.pm-tile svg{width:16px;height:16px}\n}\n";document.head.appendChild(e)})();
