function splitTop(v,sep){var a=[],d=0,c="";for(var i=0;i<v.length;i++){var ch=v.charAt(i);if(ch==="("||ch==="[")d++;if(ch===")"||ch==="]")d--;if(ch===sep&&d===0){a.push(c);c=""}else c+=ch}a.push(c);return a}
