 s=s.replace(/:where\(html\[data-theme="light"\]\)/g,LIGHT).replace(/:where\(\[data-theme="light"\]\)/g,LIGHT);
 if(/^html\b/.test(s))s=LIGHT+s.slice(4);else if(/^:root\b/.test(s))s=LIGHT+s.slice(5);else if(/^\.(tm-desktop|tm-mw|tm-app)\b/.test(s))s=LIGHT+s;else s=LIGHT+" "+s;
